update scenarios set content = '{"characters": {"staff": "l''employé"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(You approach the Tower of London ticket booth to check opening hours.)", "text_fr": "(Vous approchez la billetterie de la Tour de Londres pour vérifier les horaires d''ouverture.)", "choices": [{"text": "Excuse me, what time does the Tower open tomorrow?", "text_fr": "Excusez-moi, la Tour ouvre à quelle heure demain ?", "next": "n2"}, {"text": "Hi, is the Tower open today, and until what time?", "text_fr": "Bonjour, la Tour est ouverte aujourd''hui, et jusqu''à quelle heure ?", "next": "n2b"}]}, "n2": {"speaker": "staff", "text": "We open at 9am tomorrow, and last entry is at 5pm.", "text_fr": "On ouvre à 9h demain, et la dernière entrée est à 17h.", "choices": [{"text": "Perfect, and is it busier at certain times of day?", "text_fr": "Parfait, et c''est plus fréquenté à certains moments de la journée ?", "next": "n3"}]}, "n2b": {"speaker": "staff", "text": "Yes, open today until 5:30pm, last entry at 5pm.", "text_fr": "Oui, ouvert aujourd''hui jusqu''à 17h30, dernière entrée à 17h.", "choices": [{"text": "Great, I think I have time to visit today then.", "text_fr": "Super, je pense avoir le temps de visiter aujourd''hui alors.", "next": "n3"}]}, "n3": {"speaker": "staff", "text": "Mornings tend to be quieter, especially right at opening.", "text_fr": "Les matins ont tendance à être plus calmes, surtout juste à l''ouverture.", "choices": [{"text": "Good to know, I''ll try to arrive early then.", "text_fr": "Bon à savoir, je vais essayer d''arriver tôt alors.", "next": "n4"}]}, "n4": {"speaker": "staff", "text": "Smart choice, you''ll beat most of the tour groups that way.", "text_fr": "Choix intelligent, vous devancerez la plupart des groupes de visite comme ça.", "choices": [{"text": "Thank you so much for the helpful tips!", "text_fr": "Merci beaucoup pour les conseils utiles !", "next": "end_informed"}]}, "end_informed": {"speaker": "staff", "text": "You''re welcome, enjoy your visit!", "text_fr": "Je vous en prie, bonne visite !", "end": true, "ending_label": "Horaires d''ouverture bien compris 🏰🕐"}}}'::jsonb, is_playable = true
where title = 'Demander l''''heure d''''ouverture d''''un monument'
  and theme_id = (select id from scenario_themes where position = 15 and language_id = (select id from languages where code = 'en'));
